/// Options used to initiate the checkout-specific MFA authentication flow.
public struct BeginFlowOptions {
    /// A transaction payload generated by the merchant to represent the purchase or operation
    /// being confirmed.
    public let txPayload: String
    
    /// An identifier generated on the merchant side to identify the current checkout session.
    ///
    /// This identifier is used as a key to retrieve associated trust information.
    ///
    /// It is passed to the wallet to link the session with wallet-issued identity data,
    /// enabling secure transaction confirmation without revealing end-user identity to the merchant.
    public let merchantTrustId: String?
    
    /// The username of the user initiating the checkout session.
    ///
    /// If not provided, the wallet may retrieve it from other identifiers.
    public let username: String?
    
    /// A unique identifier used to trace and correlate all events associated with a single MFA interaction.
    ///
    /// This ID is useful for end-to-end observability, logging, and debugging across distributed systems.
    /// It can be generated by the client or left unset—if not provided, a secure random ID will be created automatically by LoginID.
    ///
    /// Example: `6957cf6e-a86c-44fb-b25a-bd97cb9ff830`
    public let traceId: String?
    
    /// An identifier for the device used in the authentication process. This property helps determine if
    /// supported authentications can be proceeded, allowing future authentications to identify the device
    /// correctly.
    ///
    /// Overrides the stored device identifier. If not provided, the SDK uses the stored value.
    public let deviceId: String?

    /// Creates a new `BeginFlowOptions` instance.
    /// - Parameters:
    ///   - txPayload: A transaction payload generated by the merchant.
    ///   - merchantTrustId: Optional trust identifier generated by the merchant.
    ///   - username: Optional username of the user initiating checkout.
    ///   - traceId: Optional correlation ID for MFA interaction tracing.
    public init(
        txPayload: String,
        merchantTrustId: String? = nil,
        username: String? = nil,
        traceId: String? = nil,
        deviceId: String? = nil
    ) {
        self.txPayload = txPayload
        self.merchantTrustId = merchantTrustId
        self.username = username
        self.traceId = traceId
        self.deviceId = deviceId
    }
}
